        strideB,
        A.data_ptr<float>(),     // A^T in column-major = A in row-major  
        K,                       // ldb (leading dimension of A^T = K)
        strideA,
        &beta,
        C.data_ptr<float>(),
        N,                       // ldc (leading dimension of C^T = N)
